 const legalGuide=globalThis.RodavoltLegalGuide;
 let legalGuideGroup='all';
 function legalGuideView(){const list=legalGuideGroup==='all'?legalGuide.items:legalGuide.items.filter(i=>i.group===legalGuideGroup);return heading('MEU ADVOGADO · MAPA DA OPERAÇÃO','Quais documentos preciso ter?','16 tipos organizados por momento de uso. Anexos podem integrar o contrato principal; documentos de ocorrência só são usados quando houver necessidade.',btn('Baixar roteiro para o advogado','legal-guide-download','primary'))+`<div class="legal-guide-boundary"><strong>Contrato ajuda a reduzir risco. Não elimina a possibilidade de processo.</strong><p>Use este roteiro com advogado e contador para fechar as condições da empresa, do carro e da lojinha. Seguro adequado, manutenção, documentos e provas também fazem parte da proteção.</p></div><div class="legal-guide-counts"><div><strong>5</strong><span>minutas disponíveis<br><small>ainda exigem revisão</small></span></div><div><strong>3</strong><span>complementos a detalhar<br><small>anexos, recibos e acerto</small></span></div><div><strong>5</strong><span>documentos a preparar<br><small>roteiros abaixo, sem minuta final</small></span></div><div><strong>3</strong><span>grupos de documentos externos<br><small>seguro, compra e fornecedores</small></span></div></div><details class="legal-business"><summary>Antes de contratar: a empresa ainda precisa ser formalizada</summary><p>Defina com contador e advogado a pessoa que assina, constituição/registro, CNPJ, poderes de representação, atividades, tributação, notas fiscais e exigências locais. O site e o nome RODAVOLT não substituem esses documentos. A lista abaixo é uma organização recomendada para o piloto, não uma lista universal de obrigações legais.</p></details><div class="legal-guide-filters" role="group" aria-label="Filtrar documentos por etapa">${[['all','Todos · 16'],...legalGuide.groups.map(g=>[g.id,g.name])].map(([id,label])=>btn(label,'legal-guide-filter',legalGuideGroup===id?'primary':'',`data-group="${id}" aria-pressed="${legalGuideGroup===id}"`)).join('')}</div><div class="legal-guide-list">${legalGuide.groups.filter(g=>list.some(i=>i.group===g.id)).map(g=>`<section aria-labelledby="legal-group-${g.id}"><div class="legal-guide-section"><h2 id="legal-group-${g.id}">${g.name}</h2><p>${g.description}</p></div><ol class="legal-guide-items" start="${list.find(i=>i.group===g.id).number}">${list.filter(i=>i.group===g.id).map(i=>`<li value="${i.number}"><span class="legal-guide-number" aria-hidden="true">${String(i.number).padStart(2,'0')}</span><div class="legal-guide-copy"><span class="eyebrow">${esc(i.kind)}</span><h3>${esc(i.title)}</h3><p>${esc(i.purpose)}</p><small><strong>Quando usar:</strong> ${esc(i.when)}</small></div><div class="legal-guide-actions">${tag(legalGuide.availability[i.availability],i.availability==='model'?'amber':'gray')}${btn('O que conferir','legal-guide-item','',`data-id="${i.id}" aria-label="O que conferir: ${esc(i.title)}"`)}${i.modelId?btn('Abrir minuta','co-model','',`data-model="${i.modelId}" aria-label="Abrir minuta: ${esc(i.title)}"`):''}</div></li>`).join('')}</ol></section>`).join('')}</div><details class="legal-guide-notes"><summary>Cuidados que o contrato sozinho não resolve</summary><ul><li>A locadora pode responder por danos a terceiros. Cláusula de ressarcimento do motorista não impede a pretensão do terceiro. <a href="${legalGuide.sources.liability.url}" target="_blank" rel="noopener noreferrer">STF · Súmula 492</a>.</li><li>Conferir a apólice para locação a terceiros e uso em aplicativo; não presumir cobertura de um seguro de uso particular.</li><li>Não presumir culpa por avaria, reter caução sem prestação de contas ou exigir confissão de dívida em branco.</li><li>O contrato e a rotina precisam ser coerentes: declaração de autonomia não afasta, sozinha, eventual discussão trabalhista.</li><li>As vendas da loja devem respeitar direitos do consumidor, regularidade dos produtos e emissão fiscal definida com o contador.</li></ul></details><details class="legal-guide-notes"><summary>Assinou pelo GOV.BR? Como conferir o arquivo</summary><ol><li>O motorista devolve o PDF original assinado pelo seu acesso individual.</li><li>A gestão confere documento, versão, partes e poderes de quem assina.</li><li>Confira autoria e integridade no <a href="${legalGuide.sources.validator.url}" target="_blank" rel="noopener noreferrer">VALIDAR do ITI</a>, por ação própria; o app não envia o arquivo ao serviço automaticamente.</li><li>Guarde o original e o resultado da validação. Registre o parecer e conclua as conferências contratuais de ambas as partes.</li></ol><p>A validação técnica não aprova cláusulas, não substitui a revisão jurídica e não libera o carro sozinha.</p></details><details class="legal-guide-notes"><summary>Fontes oficiais e data da conferência</summary><p>Conferidas em ${date(legalGuide.checkedOn)}. A aplicação ao caso e exigências específicas de Maringá/PR precisam de revisão profissional.</p><ul>${Object.values(legalGuide.sources).map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a></li>`).join('')}</ul></details><div class="section-title gap"><div><h2>Documentos e assinaturas dos motoristas</h2><p>O mapa acima orienta a preparação. A fila abaixo acompanha os documentos de cada vínculo.</p></div></div>`;}
 function legalGuideItem(id){const i=legalGuide.items.find(i=>i.id===id);if(!i)throw new RangeError('Documento não encontrado no roteiro.');return `<div class="legal-guide-detail">${tag(legalGuide.availability[i.availability],'amber')}<p><strong>${esc(i.kind)}</strong> · ${esc(i.when)}</p><p>${esc(i.purpose)}</p><h3>O que precisa estar definido</h3><ul>${i.points.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><h3>Quais provas guardar</h3><ul>${i.evidence.map(p=>`<li>${esc(p)}</li>`).join('')}</ul><div class="notice amber gap">${esc(i.caution)}</div>${i.modelId?`<div class="actions gap">${btn('Ler minuta disponível','co-model','primary',`data-model="${i.modelId}"`)}${btn('Criar rascunho deste modelo','co-new-contract','',`data-model="${i.modelId}"`)}</div>`:i.relatedModel?`<p class="caption">Este tema já aparece no texto principal. Complete o documento de apoio com as condições reais.</p>${btn('Ver cláusulas no modelo existente','co-model','',`data-model="${i.relatedModel}"`)}`:'<p class="caption">Este item tem roteiro de preparação, não texto contratual final no sistema. Obtenha ou elabore a versão com o profissional responsável.</p>'}<details class="gap"><summary>Referências para a revisão</summary><ul>${i.sources.map(k=>`<li><a href="${legalGuide.sources[k].url}" target="_blank" rel="noopener noreferrer">${esc(legalGuide.sources[k].name)}</a></li>`).join('')}</ul></details></div>`;}
 function legalGuideAction(action,e){if(action==='legal-guide-filter'){legalGuideGroup=legalGuide.groups.some(g=>g.id===e.dataset.group)?e.dataset.group:'all';render();return true;}if(action==='legal-guide-item'){const i=legalGuide.items.find(i=>i.id===e.dataset.id);if(!i)throw new RangeError('Documento não encontrado.');open(i.number+'. '+i.title,legalGuideItem(i.id));return true;}if(action==='legal-guide-download'){download('RODAVOLT-roteiro-documentos-para-advogado.txt',legalGuide.text());return true;}return false;}
